/** HOT */
export const version = "1.0.0";
export const category = "娱乐";
export const order = 510;
// Favicon: https://obj.pipi.cn/festatic/piaofang/moviepro/favicon.ico
export const platform = {
  name: "猫眼",
  icon: "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"32\" height=\"32\" viewBox=\"0 0 32 32\" data-n=\"maoyan-hot-platform-icon\"><image width=\"32\" height=\"32\" href=\"data:image/png;base64,\" data-n=\"maoyan-hot-favicon\"/></svg>",
};
import { utils } from '@findrss/util';
import { HotRankScript, Result } from "@findrss/core";

const source = {
  id: "maoyan-realtime-boxoffice",
  name: "猫眼 · 实时票房榜",
  home: "https://piaofang.maoyan.com/dashboard",
  api: "https://piaofang.maoyan.com/dashboard-ajax/movie",
};

function format_box(yuan) {
  if (!Number.isFinite(yuan) || yuan < 0) return "";
  if (yuan >= 1e8) return (yuan / 1e8).toFixed(2) + "亿";
  return (yuan / 1e4).toFixed(2) + "万";
}

export class MaoyanHotRank extends HotRankScript {
  async fetch(ctx) {
    try {
      const fetched = await utils.request_json(ctx, source.api, {
        headers: {
          Referer: source.home,
          Accept: "application/json, text/plain, */*",
        },
      });
      if (fetched.error) return fetched;
      const data = fetched.data;
      if (!data || typeof data !== "object") return Result.Err("上游未返回数据对象", "UPSTREAM_INVALID_RESPONSE");
      const list = utils.array_at(data, "movieList.list");
      if (list.error) return list;
      const entries = [], seen = new Set();
      let position = 0;
      for (const row of list.data) {
        const movie_id = String(row.movieInfo?.movieId ?? "").trim();
        if (!/^\d+$/.test(movie_id)) continue;
        const title = utils.plain_text(row.movieInfo?.movieName);
        if (!title) continue;
        const id = utils.identity(movie_id);
        if (id.error) return id;
        if (seen.has(id.data)) continue;
        seen.add(id.data);
        position += 1;
        const link = utils.absolute_url("https://www.maoyan.com/films/" + encodeURIComponent(movie_id), source.home);
        if (link.error) return link;
        const unit_num = Number(row.boxSplitUnit?.num);
        const unit_scale = row.boxSplitUnit?.unit === "亿" ? 1e8 : row.boxSplitUnit?.unit === "万" ? 1e4 : 1;
        const box_yuan = Number.isFinite(unit_num) && unit_num >= 0
          ? unit_num * unit_scale
          : Number(row.box) / 100;
        const heat_text = typeof row.boxSplitUnit?.num === "string" && typeof row.boxSplitUnit?.unit === "string"
          ? row.boxSplitUnit.num + row.boxSplitUnit.unit
          : format_box(box_yuan);
        entries.push({
          id: source.id + ":" + id.data,
          title,
          link: link.data,
          rank: position,
          pinned: false,
          heat: {
            value: Number.isFinite(box_yuan) && box_yuan >= 0 ? Math.round(box_yuan * 100) / 100 : null,
            unit: "元",
            text: heat_text,
          },
        });
      }
      ctx.log("榜单解析完成", {
        source: source.id,
        count: entries.length,
        missing_rank: entries.filter(entry => entry.rank === null).length,
      });
      return Result.Ok({
        title: source.name,
        category,
        link: source.home,
        entries,
      });
    } catch (error) {
      return Result.Err(error, error?.code ?? 'UPSTREAM_INVALID_RESPONSE');
    }
  }
}

const script = new MaoyanHotRank();

export const routes = [
  {
    "name": "猫眼 · 实时票房榜",
    "path": "/maoyan/dashboard-ajax/movie",
    "url": "piaofang.maoyan.com",
    "maintainers": ["findrss"],
    "example": "/maoyan/dashboard-ajax/movie",
    "parameters": {},
    "description": "读取猫眼专业版实时票房榜，按综合票房排序，保留片名、排名与实时票房。",
    handler: ctx => script.run(ctx),
  }
];
